package com.axelor.apps.bglocalization.service.vat.dto;

/**
 * One prepared file inside a VAT package: the EXACT generated bytes plus their integrity metadata
 * (size, SHA-256), a record count, a status and any validation messages, and a safe text preview.
 * The {@link #getContent()} bytes are the same bytes that were generated — preview and any later
 * submission use these, never a re-generated copy.
 */
public class BgVatPreparedFile {

  public static final String STATUS_OK = "ok";
  public static final String STATUS_EMPTY = "empty";
  public static final String STATUS_ERROR = "error";

  private final String scope; // sales | purchases | declaration | vies
  private final String fileName;
  private final byte[] content;
  private final long byteSize;
  private final String sha256;
  private final int recordCount;
  private final String status;
  private final String validationMessages;
  private final String textPreview;

  public BgVatPreparedFile(
      String scope,
      String fileName,
      byte[] content,
      long byteSize,
      String sha256,
      int recordCount,
      String status,
      String validationMessages,
      String textPreview) {
    this.scope = scope;
    this.fileName = fileName;
    this.content = content;
    this.byteSize = byteSize;
    this.sha256 = sha256;
    this.recordCount = recordCount;
    this.status = status;
    this.validationMessages = validationMessages;
    this.textPreview = textPreview;
  }

  public String getScope() {
    return scope;
  }

  public String getFileName() {
    return fileName;
  }

  public byte[] getContent() {
    return content;
  }

  public long getByteSize() {
    return byteSize;
  }

  public String getSha256() {
    return sha256;
  }

  public int getRecordCount() {
    return recordCount;
  }

  public String getStatus() {
    return status;
  }

  public String getValidationMessages() {
    return validationMessages;
  }

  public String getTextPreview() {
    return textPreview;
  }
}
